function Show-Fm([string]$path) {
  Write-Output "----- $path -----"
  $item = Get-Item -LiteralPath $path -Force
  $resolved = (Resolve-Path -LiteralPath $path).Path
  $root = (Resolve-Path -LiteralPath "C:\Users\magicvr\Documents\Code\goal-governance").Path
  $link = [bool]($item.Attributes -band [IO.FileAttributes]::ReparsePoint)
  Write-Output "link=$link resolved=$resolved in_repo=$($resolved.StartsWith($root, [StringComparison]::OrdinalIgnoreCase))"
  $lines = Get-Content -LiteralPath $path
  if ($lines.Count -eq 0 -or $lines[0] -ne "---") { Write-Output "NO_FRONTMATTER"; return }
  for ($i=1; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -eq "---") { break }
    Write-Output $lines[$i]
  }
}
