import json
import pathlib

root = pathlib.Path(r"C:\Users\magicvr\Documents\Code\goal-governance")
base = root / "docs/workspaces/workspace-002-methodology-skills-feedback/GOAL-019-independent-audit-lifecycle/attachments"

def summarize(path: pathlib.Path, keys):
    print("\n==", path.name, "bytes", path.stat().st_size)
    data = json.loads(path.read_text(encoding="utf-8"))
    if isinstance(data, dict):
        print("keys", list(data.keys())[:40])
        for key in keys:
            if key in data:
                value = data[key]
                text = json.dumps(value, ensure_ascii=False)
                print(key, text[:800])
    else:
        print(type(data), str(data)[:400])

summarize(base / "s3-final-rehearsal.json", ["status", "ready", "result", "summary", "counts", "exitCode", "passed", "failed", "commands"])
summarize(base / "s3-final-compatibility-report.json", ["status", "ready", "result", "verdict", "candidateRevision", "summary", "blocking"])
summarize(base / "s3-final-local-asset-verification.json", ["status", "ok", "result", "verdict", "passed", "failed", "summary"])
summarize(base / "s3-git-byte-preservation.json", ["status", "ok", "matched", "mismatched", "summary", "count"])

obs = json.loads((base / "s3-runtime/copilot-audit-12/observation.json").read_text(encoding="utf-8"))
print("\n== audit12 observation extra")
for key in obs:
    if "clerk" in key.lower() or "metadata" in key.lower() or "completion" in key.lower() or "changed" == key:
        value = obs[key]
        print(key, json.dumps(value, ensure_ascii=False)[:600])

matrix = json.loads((root / "docs/contracts/skills-consumer-compatibility-matrix.json").read_text(encoding="utf-8"))
print("\n== matrix top", list(matrix.keys()))
print("candidate", matrix.get("candidateRevision"))
consumers = matrix.get("consumers") or matrix.get("entries") or matrix.get("hosts")
print("consumer container type", type(consumers).__name__)
if isinstance(consumers, list):
    print("n", len(consumers))
    for item in consumers:
        if isinstance(item, dict):
            print({k: item.get(k) for k in ("consumer", "host", "entrypoint", "id", "status", "evidence") if k in item or True})
        else:
            print(item)
elif isinstance(consumers, dict):
    print(list(consumers.keys()))

