import json
import pathlib

root = pathlib.Path(r"C:\Users\magicvr\Documents\Code\goal-governance")
base = root / "docs/workspaces/workspace-002-methodology-skills-feedback/GOAL-019-independent-audit-lifecycle/attachments"

reh = json.loads((base / "s3-final-rehearsal.json").read_text(encoding="utf-8"))
print("releaseStatus", reh.get("releaseStatus"))
print("checksPassed", reh.get("checksPassed"))
print("generatedAt", reh.get("generatedAt"))
checks = reh.get("checks")
if isinstance(checks, list):
    print("nchecks", len(checks))
    for check in checks:
        if isinstance(check, dict):
            print({k: check.get(k) for k in ("id", "name", "status", "passed", "exitCode", "summary", "command")})
        else:
            print(check)
elif isinstance(checks, dict):
    for key, value in checks.items():
        text = json.dumps(value, ensure_ascii=False)
        print(key, text[:500])

comp = json.loads((base / "s3-final-compatibility-report.json").read_text(encoding="utf-8"))
print("\nCOMP generated", comp.get("generatedAt"))
for key in ("matrix", "mirrorVerification", "coverage", "contract"):
    value = comp.get(key)
    print(key, json.dumps(value, ensure_ascii=False)[:900])

asset = json.loads((base / "s3-final-local-asset-verification.json").read_text(encoding="utf-8"))
for key in (
    "verifiedAt", "tag", "formal", "exitCode", "skillsMembers", "coreSubsetMembers",
    "coreSubsetByteEqual", "ownedAgentsCRLFBytesPreserved", "projectConfigBytePreserved",
    "lifecycleRuleInstalled",
):
    print("ASSET", key, asset.get(key))
print("zip", json.dumps(asset.get("zipChecks"), ensure_ascii=False)[:800])

byte = json.loads((base / "s3-git-byte-preservation.json").read_text(encoding="utf-8"))
print("\nBYTE", json.dumps(byte, ensure_ascii=False))

matrix = json.loads((root / "docs/contracts/skills-consumer-compatibility-matrix.json").read_text(encoding="utf-8"))
print("\nrequiredEntrypoints", matrix.get("requiredEntrypoints"))
print("delivery", json.dumps(matrix.get("deliveryChannels"), ensure_ascii=False)[:800])
for consumer in matrix["consumers"]:
    evidence = consumer.get("evidence") or consumer.get("runtimeEvidence") or consumer.get("records")
    # find list fields
    lists = {k: v for k, v in consumer.items() if isinstance(v, list)}
    print("consumer", consumer.get("id"), "list keys", {k: len(v) for k, v in lists.items()})
    for key, value in lists.items():
        if value and isinstance(value[0], str):
            print(" ", key, value)
        elif value and isinstance(value[0], dict):
            for row in value:
                print(" ", key, {rk: row.get(rk) for rk in ("entrypoint", "id", "path", "record", "verdict", "status")})

