$paths = @(
  "docs/releases/runtime/v0.15.1/github-copilot-cli-audit-2026-11-13-r12.json",
  "docs/workspaces/workspace-002-methodology-skills-feedback/GOAL-019-independent-audit-lifecycle/attachments/s3-runtime/copilot-audit-12/changed/docs/workspaces/workspace-002-synthetic/GOAL-019-synthetic-counter/03-audit/A-001-counter-count-contract.md"
)
foreach ($p in $paths) {
  $work = (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLower()
  $index = git rev-parse --verify ":$p" 2>$null
  if (-not $index) { Write-Output "$p NOT_STAGED work=$work"; continue }
  $blob = git cat-file blob ":$p" | git hash-object --stdin
  # hash-object of piped content may change newlines. Use git rev-parse blob and git hash-object --path
  $raw = git show ":$p" --no-textconv
  # Better: git hash-object the index blob directly
  Write-Output "$p staged=$index work=$work"
}
# Compare index blob hash to git hash-object of working tree bytes without conversion
foreach ($p in $paths) {
  $index = git rev-parse --verify ":$p" 2>$null
  $workObj = git hash-object -- "$p"
  Write-Output "compare $p index=$index workobj=$workObj equal=$($index -eq $workObj)"
}

